-- 545: Original BrillaPrep WASSCE Core Mathematics sprint 3 beta questions, part 7 of 10 (batch wassce-core-math-sprint3-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_545_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_545_guard;
INSERT INTO _migration_545_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_031' AND NOT (q.topic_id IS 'topic_wassce_p2_math_qdr' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Find the minimum value of y = x² − 4x + 3.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 3","B. −4","C. −1","D. 2"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Complete the square: y = (x − 2)² − 4 + 3 = (x − 2)² − 1. Since (x − 2)² ≥ 0, the least value of y is −1, occurring at x = 2. (2 is the x-value at the minimum, not the minimum value; 3 is just the constant term.) Therefore the correct answer is C: −1.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_031' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_545_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_032' AND NOT (q.topic_id IS 'topic_wassce_p2_math_qdr' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Calculate the discriminant of the quadratic equation 2x² + 3x + 1 = 0.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 17","B. 5","C. −7","D. 1"]' AND q.correct_answer IS 'D' AND q.explanation IS 'The discriminant is b² − 4ac with a = 2, b = 3 and c = 1: 3² − 4(2)(1) = 9 − 8 = 1. The positive discriminant confirms two real roots. (17 wrongly adds 9 + 8 instead of subtracting.) Therefore the correct answer is D: 1.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_032' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_545_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_033' AND NOT (q.topic_id IS 'topic_wassce_p2_math_trg' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Write down the value of sin 30°.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 1/2","B. √3/2","C. √2/2","D. 1"]' AND q.correct_answer IS 'A' AND q.explanation IS 'sin 30° is a standard exact value: 1/2. (√3/2 is the value of sin 60°, confusing the two complementary special angles.) Therefore the correct answer is A: 1/2.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Write down' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_033' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_545_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_034' AND NOT (q.topic_id IS 'topic_wassce_p2_math_trg' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Write down the value of tan 45°.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 0","B. 1","C. 1/√3","D. √3"]' AND q.correct_answer IS 'B' AND q.explanation IS 'At 45° the opposite and adjacent sides of the right-angled triangle are equal, so tan 45° = opposite ÷ adjacent = 1. (√3 is tan 60° and 1/√3 is tan 30°.) Therefore the correct answer is B: 1.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Write down' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_034' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_545_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_035' AND NOT (q.topic_id IS 'topic_wassce_p2_math_trg' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A right-angled triangle has shorter sides of 3 cm and 4 cm. Find the length of the hypotenuse.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 7 cm","B. 12 cm","C. 5 cm","D. √7 cm"]' AND q.correct_answer IS 'C' AND q.explanation IS 'By the theorem of Pythagoras: hypotenuse = √(3² + 4²) = √(9 + 16) = √25 = 5 cm. (7 cm just adds the two sides; √7 cm subtracts the squares, which applies only when the hypotenuse is given.) Therefore the correct answer is C: 5 cm.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_035' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wcms3_031', 'topic_wassce_p2_math_qdr', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Find the minimum value of y = x² − 4x + 3.', 'multiple_choice', NULL, '["A. 3","B. −4","C. −1","D. 2"]', 'C', 'Complete the square: y = (x − 2)² − 4 + 3 = (x − 2)² − 1. Since (x − 2)² ≥ 0, the least value of y is −1, occurring at x = 2. (2 is the x-value at the minimum, not the minimum value; 3 is just the constant term.) Therefore the correct answer is C: −1.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Find', 'AO2', NULL, NULL, 'board_waec');
